def watershed_sizes(heights: list[list[int]]) -> list[tuple[int, int, int]]:
    """
    Calculates the watershed sizes for a given grid of terrain heights.

    A sink is a cell with no strictly lower neighbors. Water flows from 
    each cell to the lowest strictly lower neighbor (with a specific 
    priority order for ties).
    """
    if not heights or not heights[0]:
        return []

    rows = len(heights)
    cols = len(heights[0])

    # next_step[r][c] will store the (nr, nc) that cell (r, c) flows to.
    # If it's a sink, it will point to itself.
    next_step = [[None for _ in range(cols)] for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            h = heights[r][c]
            candidates = []
            # Order of neighbors to check for flow: North, East, South, West
            directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if heights[nr][nc] < h:
                        # Store the coordinate and its height
                        candidates.append((nr, nc, heights[nr][nc]))

            if not candidates:
                # No lower neighbors, so this cell is a sink
                next_step[r][c] = (r, c)
            else:
                # Find the minimum height among strictly lower neighbors
                min_h = min(cand[2] for cand in candidates)
                # Select the first neighbor in the specified priority order
                # that has this minimum height
                for nr, nc, nh in candidates:
                    if nh == min_h:
                        next_step[r][c] = (nr, nc)
                        break

    # Use an iterative path-following approach with memoization to 
    # find the ultimate sink for every cell.
    final_sink = [[None for _ in range(cols)] for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if final_sink[r][c] is not None:
                continue

            path = []
            curr_r, curr_c = r, c
            while final_sink[curr_r][curr_c] is None:
                path.append((curr_r, curr_c))
                nr, nc = next_step[curr_r][curr_c]
                if (nr, nc) == (curr_r, curr_c):
                    # Found the sink for this path
                    for pr, pc in path:
                        final_sink[pr][pc] = (curr_r, curr_c)
                    break
                else:
                    curr_r, curr_c = nr, nc
                    # If we hit a cell whose sink is already known
                    if final_sink[curr_r][curr_c] is not None:
                        for pr, pc in path:
                            final_sink[pr][pc] = final_sink[curr_r][curr_c]
